كتابة خوارزمية Binary Search خالية من ثغرة الـ Integer Overflow في كوتلن:
```kotlin
fun binarySearch(sortedList: IntArray, target: Int): Int {
    var low = 0
    var high = sortedList.size - 1

    while (low <= high) {
        // ✅ تفادي طفح الأرقام الصحيحة (Integer Overflow Safe):
        val mid = low + (high - low) / 2
        val midVal = sortedList[mid]

        when {
            midVal == target -> return mid // تم العثور على العنصر بنجاح!
            midVal < target -> low = mid + 1 // الهدف في النصف الأيمن
            else -> high = mid - 1 // الهدف في النصف الأيسر
        }
    }
    return -1 // العنصر غير موجود
}
```

طرق كوتلن الفعالة لاكتشاف وإزالة التكرار مع الحفاظ على الأداء والذاكرة:
```kotlin
data class User(val id: Long, val name: String)

// 1. الطريقة الأسرع والأكثر شيوعاً (O(n) time, O(n) space):
fun removeDuplicatesFast(users: List<User>): List<User> {
    return users.distinctBy { it.id }
}

// 2. الكشف عن المكررات فقط وحفظها (O(n) time, O(n) space):
fun findDuplicates(items: List<String>): Set<String> {
    val seen = HashSet<String>()
    val duplicates = HashSet<String>()
    for (item in items) {
        if (!seen.add(item)) {
            duplicates.add(item) // تم رصده مسبقاً، إذاً هو مكرر!
        }
    }
    return duplicates
}

// 3. الطريقة الصديقة للذاكرة الصارمة (O(n log n) time, O(1) extra space):
fun removeDuplicatesInPlace(primitiveIds: LongArray): Int {
    primitiveIds.sort() // فرز موضعي O(n log n)
    if (primitiveIds.isEmpty()) return 0
    var uniqueIndex = 0
    for (i in 1 until primitiveIds.size) {
        if (primitiveIds[i] != primitiveIds[uniqueIndex]) {
            uniqueIndex++
            primitiveIds[uniqueIndex] = primitiveIds[i]
        }
    }
    return uniqueIndex + 1 // عدد العناصر الفريدة، بدون تخصيص أي كائن على الـ Heap!
}
```

تحليل عملي للفرق بين المتسلسلة الحسابية والمتسلسلة الهندسية في كود كوتلن:
```kotlin
// 1. المتسلسلة الحسابية O(n^2):
fun printPairs(n: Int) {
    var totalSteps = 0
    for (i in 0 until n) {
        for (j in i until n) { // j يعتمد على i
            totalSteps++
        }
    }
    // totalSteps = n * (n + 1) / 2 -> O(n^2)
}

// 2. المتسلسلة الهندسية O(n) (حلقة متداخلة تبدو مخادعة ولكنها خطية!):
fun geometricDependentLoop(n: Int) {
    var totalSteps = 0
    var i = 1
    while (i <= n) {
        for (j in 0 until i) { // j يعتمد على i المتضاعف
            totalSteps++
        }
        i *= 2 // تضاعف أسي
    }
    // الخطوات: 1 + 2 + 4 + 8 + ... + 2^k = 2 * n - 1 -> O(n)!
}
```

تصميم LRU Cache متكامل في كوتلن، واستخدام `LruCache` الرسمي في أندرويد:
```kotlin
// 1. تصميم LRU Cache من الصفر باستخدام Doubly LinkedList + HashMap:
class CustomLruCache<K, V>(private val capacity: Int) {
    private class Node<K, V>(val key: K, var value: V, var prev: Node<K, V>? = null, var next: Node<K, V>? = null)
    private val map = HashMap<K, Node<K, V>>()
    private val head = Node<K?, V?>(null, null)
    private val tail = Node<K?, V?>(null, null)

    init { head.next = tail; tail.prev = head }

    fun get(key: K): V? {
        val node = map[key] ?: return null
        moveToHead(node) // O(1) نقل للمقدمة كأحدث عنصر
        return node.value
    }

    fun put(key: K, value: V) {
        map[key]?.let {
            it.value = value
            moveToHead(it)
        } ?: run {
            if (map.size >= capacity) removeTail() // O(1) طرد الأقدم
            val newNode = Node(key, value)
            map[key] = newNode
            addToHead(newNode)
        }
    }

    private fun removeNode(node: Node<K, V>) {
        node.prev?.next = node.next
        node.next?.prev = node.prev
    }
    private fun addToHead(node: Node<K, V>) {
        node.next = head.next
        node.prev = head
        head.next?.prev = node
        head.next = node
    }
    private fun moveToHead(node: Node<K, V>) { removeNode(node); addToHead(node) }
    private fun removeTail() { tail.prev?.takeIf { it != head }?.let { removeNode(it); map.remove(it.key) } }
}
```

تطبيق خوارزميتي BFS و DFS لفحص شجرة الـ Android View للعثور على زر معين:
```kotlin
// نموذج شجرة الواجهة المبسط:
class ViewNode(val id: String, val children: List<ViewNode> = emptyList())

// 1. BFS باستخدام Queue (الأفضل للعثور على أقرب عنصر سطحي):
fun findViewBfs(root: ViewNode, targetId: String): ViewNode? {
    val queue = ArrayDeque<ViewNode>()
    queue.addLast(root)
    while (queue.isNotEmpty()) {
        val current = queue.removeFirst()
        if (current.id == targetId) return current
        for (child in current.children) {
            queue.addLast(child)
        }
    }
    return null
}

// 2. DFS باستخدام Recursion (الأفضل لفحص العمق واكتشاف المسارات):
fun findViewDfs(current: ViewNode, targetId: String): ViewNode? {
    if (current.id == targetId) return current
    for (child in current.children) {
        val found = findViewDfs(child, targetId)
        if (found != null) return found
    }
    return null
}
```

